sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var saved = gs.getProperty('x_fed_day2_ops.nonprod_instances', '');
  try {
    gs.setProperty('x_fed_day2_ops.nonprod_instances', 'some-other-instance');
    var env = new x_fed_day2_ops.Day2Env();
    if (env.isTestMode()) { stepResult.setFailed('test_mode honoured on an undeclared instance (P0-5 regressed)'); return; }
    if (!env.isRefusing()) { stepResult.setFailed('property set on an undeclared instance did not trigger refusal'); return; }
    var gate = new x_fed_day2_ops.EntraHelpdeskGate();
    var pre = gate.preflight({ requester_id: 'r', approver_id: 'a' });
    if (pre.ok) { stepResult.setFailed('preflight passed while the environment guard was refusing'); return; }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.nonprod_instances', saved);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) { stepResult.setFailed('precondition not met: test_mode is not active on this instance'); return; }
  var stamp = env.evidenceStamp();
  if (stamp.test_mode !== true || stamp.synthetic !== true) {
    stepResult.setFailed('evidence stamp does not mark the record synthetic under test_mode');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
